from base import *
rows=[("◷","Start Timer","for <span class='pill'>25</span> minutes"),("☕","Keep Mac Awake","<span class='pill'>until stopped ▾</span>"),("▤","Add to Shelf","<span class='pill'>Shortcut Input</span>"),("▢","Open Notch","on <span class='pill'>Home ▾</span>")]
sc='<div class="win" style="width:440px"><div class="tb"><i></i><i></i><i></i><span class="s" style="font-size:12px;margin-left:10px">Shortcuts · PancakeNotch actions</span></div><div style="padding:14px">'+''.join(f'<div class="card" style="padding:10px 14px;margin-bottom:8px;display:flex;align-items:center;gap:10px;font-size:13px"><span style="width:26px;height:26px;border-radius:7px;background:rgba(255,255,255,.13);display:flex;align-items:center;justify-content:center">{i}</span><b>{a}</b><span class="s">{b}</span></div>' for i,a,b in rows)+'</div></div>'
term='<div class="win" style="width:470px"><div class="tb"><i></i><i></i><i></i><span class="s" style="font-size:12px;margin-left:10px">Terminal / Raycast / Stream Deck</span></div><div style="padding:14px;font:12.5px Menlo,monospace;line-height:1.9"><span class="q">$</span> open "pancakenotch://timer/start?minutes=25"<br><span class="q">$</span> open "pancakenotch://keepawake/start?until=stopped"<br><span class="q">$</span> open "pancakenotch://shelf/add?path=~/build/app.zip"<br><span class="q">$</span> open "pancakenotch://open?page=home"</div></div>'
body=cap("Actions in the Shortcuts app and the URL scheme")+'<div class="row">'+sc+term+'</div>'
body+=cap("Result · the timer and Keep Awake start without touching the notch")+compact('<span>☕</span>','<span class="ring" style="--p:2%"></span><span>25:00</span>')
open("m02.html","w").write(page("Shortcuts and URL actions","Run PancakeNotch from Shortcuts, Spotlight, launchers and scripts.",body))
